// T016 (003) + T022 (004): docs/design/narration/lines.json → docs/design/narration-script.md + prototype/assets/data/audio-manifest.js.
// Manifest 2.0.0 (004 contracts/audio-manifest.md): each line per language is
//   recorded — a human file prototype/assets/audio/<lang>/<id>.m4a          (always preferred)
//   scratch  — only a temporary AI file prototype/assets/audio-scratch/<lang>/<id>.mp3 (RB-1: never released)
//   pending  — neither (the caption is shown; nothing is ever synthesised)
// --check: writes nothing; fails if a generated file is out of date, a line is too long, or a spoken key is missing.
import { readFileSync, writeFileSync, existsSync, readdirSync } from 'node:fs';
import path from 'node:path';
import Ajv2020 from 'ajv/dist/2020.js';
import { ROOT, readJson } from './lib.mjs';

const LINES = path.join(ROOT, 'docs/design/narration/lines.json');
const SCHEMA = path.join(ROOT, 'specs/003-brand-voice-interactive/contracts/narration-lines.schema.json');
const SCRIPT = path.join(ROOT, 'docs/design/narration-script.md');
const MANIFEST = path.join(ROOT, 'prototype/assets/data/audio-manifest.js');
const AUDIO = path.join(ROOT, 'prototype/assets/audio');
const SCRATCH = path.join(ROOT, 'prototype/assets/audio-scratch');
const MANIFEST_VERSION = '2.0.0';
const check = process.argv.includes('--check');

const doc = readJson(LINES);
const ajv = new Ajv2020({ allErrors: true, strict: false });
if (!ajv.validate(readJson(SCHEMA), doc)) {
  console.error('lines.json does not match narration-lines.schema.json:');
  for (const e of ajv.errors) console.error(`  ${e.instancePath || '/'} ${e.message}`);
  process.exit(1);
}

const problems = [];
const ids = new Set();
const words = (t) => t.replace(/[^\p{L}\p{N}'\s-]/gu, ' ').split(/\s+/).filter(Boolean).length;
const estimate = (t) => +(words(t) * 60 / doc.wordsPerMinute).toFixed(1);
for (const l of doc.lines) {
  if (ids.has(l.id)) problems.push(`duplicate line id ${l.id}`);
  ids.add(l.id);
  if (/\{[a-z]+\}/i.test(l.text)) problems.push(`${l.id}: recorded lines cannot contain variables ("${l.text}")`);
  const est = estimate(l.text);
  if (est > l.maxSeconds) problems.push(`${l.id}: ~${est}s at ${doc.wordsPerMinute} wpm is longer than maxSeconds ${l.maxSeconds}`);
}

// Manifest: every id in every language; recorded beats scratch beats pending.
const lines = {};
const counts = {};
let recorded = 0;
const listDir = (dir, ext) => new Set(existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith(ext)) : []);
for (const lang of doc.languages) {
  lines[lang] = {};
  counts[lang] = { recorded: 0, scratch: 0, pending: 0 };
  const human = listDir(path.join(AUDIO, lang), '.m4a');
  const scratch = listDir(path.join(SCRATCH, lang), '.mp3');
  for (const l of doc.lines) {
    const rec = human.has(`${l.id}.m4a`), scr = scratch.has(`${l.id}.mp3`);
    const status = rec ? 'recorded' : scr ? 'scratch' : 'pending';
    counts[lang][status]++;
    if (rec) recorded++;
    const scratchFile = scr ? `assets/audio-scratch/${lang}/${l.id}.mp3` : null;
    lines[lang][l.id] = { status, file: rec ? `assets/audio/${lang}/${l.id}.m4a` : scratchFile, scratchFile, maxSeconds: l.maxSeconds };
  }
  for (const f of human) if (!ids.has(f.replace(/\.m4a$/, ''))) problems.push(`audio/${lang}/${f}: no line with that id in lines.json`);
  for (const f of scratch) if (!ids.has(f.replace(/\.mp3$/, ''))) problems.push(`audio-scratch/${lang}/${f}: no line with that id in lines.json`);
}
const text = Object.fromEntries(doc.lines.map((l) => [l.id, l.text]));
const manifest = {
  version: MANIFEST_VERSION, linesVersion: doc.version, defaultLanguage: doc.defaultLanguage, regionLanguage: doc.regionLanguage,
  languages: doc.languages, counts, text, lines,
};
const outputs = new Map();
outputs.set(MANIFEST, `/* GENERATED by tools/design/build-narration.mjs from docs/design/narration/lines.json — do not edit.
   Human recordings: drop <lineId>.m4a into assets/audio/<lang>/ (spec 003 FR-019).
   Scratch voice (temporary, 004 RB-1): assets/audio-scratch/<lang>/<lineId>.mp3, made by scripts/generate-scratch-voice.
   Re-run the script after adding or removing either. Never any synthesised speech at runtime. */
window.KC = window.KC || {};
KC.audioManifest = ${JSON.stringify(manifest, null, 1)};
`);

// Actor's script, grouped by screen.
const byScreen = {};
for (const l of doc.lines) (byScreen[l.screen] = byScreen[l.screen] || []).push(l);
const order = ['welcome', 'age-select', 'avatar', 'parent-gate', 'home', 'mission-intro', 'activity-find', 'activity-sort', 'activity-count',
  'decision', 'result-save', 'result-spend', 'summary', 'reward', 'wallet', 'progress', 'daily-challenge', 'level-up', 'badge-detail', 'profile',
  'm7-intro', 'm7-decision', 'm7-result', 'm7-summary', 'm10-intro', 'm10-resource', 'm10-market', 'm10-result', 'm10-summary',
  'm13-intro', 'm13-budget', 'm13-market', 'm13-result', 'm13-summary', 'any'];
const screens = Object.keys(byScreen).sort((a, b) => (order.indexOf(a) + 99 * (order.indexOf(a) < 0)) - (order.indexOf(b) + 99 * (order.indexOf(b) < 0)));
const esc = (s) => String(s || '').replace(/\|/g, '\\|');
let md = `# KudiCubs Narration Script

**For the voice actor.** Read [voice-direction-brief.md](./voice-direction-brief.md) first.
Generated by \`tools/design/build-narration.mjs\` from \`docs/design/narration/lines.json\` (v${doc.version}) — edit the JSON, not this file.

- **First recording language**: \`${doc.defaultLanguage}\` (Ghanaian English — **provisional**, pending client confirmation).
- **Pace**: about ${doc.wordsPerMinute} words per minute. **Every line ≤ 8 seconds, one idea per line.**
- **${doc.lines.length} lines.** Recorded so far: ${counts[doc.defaultLanguage].recorded} of ${doc.lines.length} in ${doc.defaultLanguage}. (A temporary scratch voice covers ${counts[doc.defaultLanguage].scratch} lines for demos only; it never replaces this recording.)
- **File name** = the line ID + \`.wav\` (masters) or \`.m4a\` (prototype), e.g. \`intro.say.wav\`.

`;
for (const s of screens) {
  md += `## ${s === 'any' ? 'Shared (navigation, numbers, hints)' : 'Screen: `' + s + '`'}\n\n| ID | Line | Delivery | ≤ s (est.) | Idea | Say it like |\n|---|---|---|---|---|---|\n`;
  for (const l of byScreen[s]) {
    md += `| \`${l.id}\`${l.region ? ` (${l.region.toUpperCase()})` : ''} | ${esc(l.text)} | ${l.delivery} | ${l.maxSeconds} (${estimate(l.text)}) | ${esc(l.idea)} | ${esc(l.pronunciation)}${l.notes ? ' — ' + esc(l.notes) : ''} |\n`;
  }
  md += '\n';
}
md += `## File naming table\n\n| ID | Master file | Prototype file |\n|---|---|---|\n${doc.lines.map((l) => `| \`${l.id}\` | \`${l.id}.wav\` | \`prototype/assets/audio/<lang>/${l.id}.m4a\` |`).join('\n')}\n`;
outputs.set(SCRIPT, md);
for (const [file, body] of outputs) {
  if (!check) writeFileSync(file, body);
  else if (!existsSync(file) || readFileSync(file, 'utf8') !== body) problems.push(`${path.relative(ROOT, file)} is out of date: run node tools/design/build-narration.mjs`);
}

if (check) {
  // Every key the prototype speaks must exist.
  const src = ['app.js', 'screens.js', 'activities.js', 'screens-bands.js', 'screens-parent.js', 'missions/band-7-9.js', 'missions/band-10-12.js', 'missions/band-13-15.js'].map((f) => readFileSync(path.join(ROOT, 'prototype/assets', f), 'utf8')).join('\n');
  const used = new Set();
  for (const m of src.matchAll(/KC\.voice\.play\('([a-z0-9_.]+)'/g)) used.add(m[1]);
  for (const m of src.matchAll(/(?:say|line|narration|hear):\s*'([a-z][a-z0-9_]*\.[a-z0-9_.]+)'/g)) used.add(m[1]);
  for (const m of src.matchAll(/'data-say':\s*'([a-z0-9_.]+)'/g)) used.add(m[1]);
  for (const k of used) {
    if (k.endsWith('.')) { if (![...ids].some((id) => id.startsWith(k))) problems.push(`prototype speaks '${k}…' but no line starts with it`); continue; } // dynamic prefix, e.g. 'num.' + n
    if (!ids.has(k)) problems.push(`prototype speaks '${k}' but it is not in lines.json`);
  }
  for (const l of doc.lines) if (l.maxSeconds > 8) problems.push(`${l.id}: maxSeconds over 8`);
}

if (problems.length) {
  console.error(problems.join('\n'));
  console.error(`\n${problems.length} narration problem(s).`);
  process.exit(1);
}
const c = counts[doc.defaultLanguage];
console.log(`narration v${doc.version} (manifest ${MANIFEST_VERSION}): ${doc.lines.length} lines × ${doc.languages.length} languages; ${doc.defaultLanguage} recorded ${c.recorded} · scratch ${c.scratch} · pending ${c.pending}${check ? ' (check OK)' : ' → narration-script.md + audio-manifest.js'}`);
